export function isUuid(value) {
  return typeof value === 'string' && /^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(value)
}

/** Accept only the object layout generated by create-upload for this row. */
export function isOriginalKey(videoId, key) {
  if (!isUuid(videoId) || typeof key !== 'string') return false
  const directory = `videos/${videoId}/`
  return key.startsWith(directory) && /^original\.[a-z0-9]{1,8}$/.test(key.slice(directory.length))
}
